for i in range(1,11):
    print(i)
    if(i==6):
        break   #break statement is used to terminate the loop when a certain condition is met. In this case, the loop will be terminated when i is equal to 6. The break statement can be used in both for and while loops. When the break statement is executed, the loop will be terminated and the program will continue with the next statement after the loop. If there are nested loops, the break statement will only terminate the innermost loop in which it is present.